  // 2. Retrieve session list
  const sessions = await api.functional.todoApp.guest.sessions.index(
    memberConnection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppMemberSession.IRequest,
    },
  );
